#!/usr/bin/env bash
# ============================================================================
# EWA batch3-ewa — DEFENSE & MONITORING
# AdaptiveDefense, TWAPOracleEngine (live ETH/USD), FeeAdaptationEngine, EngineHub (3 live engines).
#
# RUN (Termux):
#   cd ~/eva-contracts && git pull
#   export PK=0x...                 # founder signer key (never paste in chat)
#   export CONFIRM_DEFAULTS=yes     # ONLY after reviewing the defaults below
#   bash deployments/batch3-ewa-ewa.sh
#   unset PK && history -c
#
# Deployed addresses append to deployments/ewa-addresses.env (shared across
# batches). Every contract verifies on-chain post-deploy; any mismatch aborts.
# Founder signs every transaction. Nothing here touches mainnet by itself.
# ============================================================================
set -euo pipefail

RPC="${RPC:-https://mainnet.base.org}"
EWA_CORE=0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB
FOUNDER=0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8
ETHUSD_FEED=0x71041dddad3595F9CEd3DcCFBe3D1F4b0a16Bb70
: "${PK:?export PK=0x... first}"

echo "=================================================================="
echo "EWA batch3-ewa — DEFENSE & MONITORING"
echo "Founder: REVIEW these defaults/params before proceeding:"
echo "  defense registry = <INCIDENTREG from batch1> (run batch1 first)"
echo "  twap feed        = ETH/USD 0x71041dddad3595F9CEd3DcCFBe3D1F4b0a16Bb70 (verified Chainlink)"
echo "  enginehub regs   = 5 entries on 3 LIVE engines: DEFENSE_LEVEL, TWAP_FAST/SLOW_USD8, BUY/SELL_TAX_BP"
echo "  EXCLUDED (dead on EWA_Core): LiquidityDepth, ReserveSolvency, VolatilitySurface"
echo "  feev2: tiers=$0.01/$1/$100/$1000 signalMaxAge=1d [FIXED 2026-10-02: omega scale guard in code]"
echo "  danger: weights=100k x12 NEUTRAL placeholder (founder modeling decision later)"
echo "=================================================================="
if [ "${CONFIRM_DEFAULTS:-}" != "yes" ]; then
  echo "ABORT: set CONFIRM_DEFAULTS=yes only after reviewing the above."
  exit 1
fi

ADDR_FILE="$(cd "$(dirname "$0")" && pwd)/ewa-addresses.env"
touch "$ADDR_FILE"
# shellcheck disable=SC1090
source "$ADDR_FILE"
save_addr() { printf '%s=%s\n' "$1" "$2" >> "$ADDR_FILE"; echo "  saved: $1=$2"; }
eq_addr() { [ "$(printf '%s' "$1" | tr 'A-Z' 'a-z')" = "$(printf '%s' "$2" | tr 'A-Z' 'a-z')" ]; }

DEPLOYER="$(cast wallet address --private-key "$PK")"
echo "deployer: $DEPLOYER"
echo "rpc: $RPC"
echo ""

# ===== AdaptiveDefense =====
echo "=== AdaptiveDefense ==="
: "${INCIDENTREG:?need INCIDENTREG from batch1}"
DEFENSE_
DEFENSE_ARGS=$(cast abi-encode "constructor(address)" $INCIDENTREG)
DEFENSE_ARGS=${DEFENSE_ARGS#0x}
DEFENSE=$(cast send --rpc-url $RPC --private-key $PK --create ${DEFENSE_BC}${DEFENSE_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${DEFENSE:-}" ]; then echo "FATAL: AdaptiveDefense deploy failed"; exit 1; fi
echo "AdaptiveDefense = $DEFENSE"
save_addr DEFENSE $DEFENSE
sleep 5
# verify registry (actual getter name from source: REGISTRY())
eq_addr "$(cast call $DEFENSE "REGISTRY()(address)" --rpc-url $RPC)" "$INCIDENTREG" || { echo "FATAL: AdaptiveDefense registry mismatch"; exit 1; }
sleep 5

# ===== TWAPOracleEngine =====
echo "=== TWAPOracleEngine ==="
TWAP_
TWAP_ARGS=$(cast abi-encode "constructor(address)" 0x71041dddad3595F9CEd3DcCFBe3D1F4b0a16Bb70)
TWAP_ARGS=${TWAP_ARGS#0x}
TWAP=$(cast send --rpc-url $RPC --private-key $PK --create ${TWAP_BC}${TWAP_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${TWAP:-}" ]; then echo "FATAL: TWAPOracleEngine deploy failed"; exit 1; fi
echo "TWAPOracleEngine = $TWAP"
save_addr TWAP $TWAP
sleep 5
# verify feed == ETHUSD (actual getter name from source)
eq_addr "$(cast call $TWAP "FEED()(address)" --rpc-url $RPC)" "0x71041dddad3595F9CEd3DcCFBe3D1F4b0a16Bb70" || { echo "FATAL: TWAPOracleEngine feed mismatch"; exit 1; }
sleep 5

# ===== FeeAdaptationEngine =====
echo "=== FeeAdaptationEngine ==="
FEEADAPT_
FEEADAPT=$(cast send --rpc-url $RPC --private-key $PK --create ${FEEADAPT_BC} | grep -i contractAddress | awk '{print $2}')
if [ -z "${FEEADAPT:-}" ]; then echo "FATAL: FeeAdaptationEngine deploy failed"; exit 1; fi
echo "FeeAdaptationEngine = $FEEADAPT"
save_addr FEEADAPT $FEEADAPT
sleep 5
# verify: a real read call from source
cast call --rpc-url $RPC $FEEADAPT "BUY_BASE()(uint256)"
cast call --rpc-url $RPC $FEEADAPT "engineId()(bytes32)"
sleep 5

# ===== EVA_EngineHub =====
# regs: 5 entries on 3 LIVE engines only (dead engines LiquidityDepth/ReserveSolvency/VolatilitySurface EXCLUDED - poke() reverts on EWA_Core)
echo "=== EVA_EngineHub ==="
: "${DEFENSE:?need DEFENSE}"
: "${TWAP:?need TWAP}"
: "${FEEADAPT:?need FEEADAPT}"
K_DEFENSE="$(cast keccak "EVA.SIG.DEFENSE_LEVEL")"
K_FAST="$(cast keccak "EVA.SIG.TWAP_FAST_USD8")"
K_SLOW="$(cast keccak "EVA.SIG.TWAP_SLOW_USD8")"
K_BUY="$(cast keccak "EVA.SIG.BUY_TAX_BP")"
K_SELL="$(cast keccak "EVA.SIG.SELL_TAX_BP")"
ENGINEHUB_
ENGINEHUB_REGS="[(${K_DEFENSE},${DEFENSE}),(${K_FAST},${TWAP}),(${K_SLOW},${TWAP}),(${K_BUY},${FEEADAPT}),(${K_SELL},${FEEADAPT})]"
ENGINEHUB_ARGS=$(cast abi-encode "constructor((bytes32,address)[])" "$ENGINEHUB_REGS")
ENGINEHUB_ARGS=${ENGINEHUB_ARGS#0x}
ENGINEHUB=$(cast send --rpc-url $RPC --private-key $PK --create ${ENGINEHUB_BC}${ENGINEHUB_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${ENGINEHUB:-}" ]; then echo "FATAL: EVA_EngineHub deploy failed"; exit 1; fi
echo "EVA_EngineHub = $ENGINEHUB"
save_addr ENGINEHUB $ENGINEHUB
sleep 5
# verify: registeredCount == 5 and engineOf mappings
[ "$(cast call $ENGINEHUB "registeredCount()(uint256)" --rpc-url $RPC)" = "5" ] || { echo "FATAL: EVA_EngineHub registeredCount != 5"; exit 1; }
eq_addr "$(cast call $ENGINEHUB "engineOf(bytes32)(address)" $K_BUY --rpc-url $RPC)" "$FEEADAPT" || { echo "FATAL: EVA_EngineHub engineOf(BUY) mismatch"; exit 1; }
eq_addr "$(cast call $ENGINEHUB "engineOf(bytes32)(address)" $K_FAST --rpc-url $RPC)" "$TWAP" || { echo "FATAL: EVA_EngineHub engineOf(FAST) mismatch"; exit 1; }
eq_addr "$(cast call $ENGINEHUB "engineOf(bytes32)(address)" $K_DEFENSE --rpc-url $RPC)" "$DEFENSE" || { echo "FATAL: EVA_EngineHub engineOf(DEFENSE) mismatch"; exit 1; }
sleep 5


echo ""
echo "=================================================================="
echo "batch3-ewa complete — addresses this batch:"
echo "  DEFENSE=${DEFENSE:-MISSING}"
echo "  TWAP=${TWAP:-MISSING}"
echo "  FEEADAPT=${FEEADAPT:-MISSING}"
echo "  ENGINEHUB=${ENGINEHUB:-MISSING}"
# ===== EVA_FeeAdaptationV2 =====
echo "=== EVA_FeeAdaptationV2 ==="
FEEV2_
FEEV2_ARGS=$(cast abi-encode "constructor(uint256,uint256,uint256,uint256,uint256)" 1000000 100000000 10000000000 100000000000 86400)
FEEV2_ARGS=${FEEV2_ARGS#0x}
FEEV2=$(cast send --rpc-url $RPC --private-key $PK --create ${FEEV2_BC}${FEEV2_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${FEEV2:-}" ]; then echo "FATAL: EVA_FeeAdaptationV2 deploy failed"; exit 1; fi
echo "EVA_FeeAdaptationV2 = $FEEV2"
save_addr FEEV2 $FEEV2
sleep 5
eq_addr "$(cast call $FEEV2 "engineId()(bytes32)" --rpc-url $RPC)" "0xb468194568757d9ab1f17521d5faa7874354f62589848b7ad41e6b38c9bb9a1b" || { echo "FATAL: FEEV2 engineId mismatch"; exit 1; }
sleep 5


# ===== EVA_DangerScore =====
echo "=== EVA_DangerScore ==="
DANGER_
DANGER_ARGS=$(cast abi-encode "constructor(address,uint256[12])" $ENGINEHUB "[100000,100000,100000,100000,100000,100000,100000,100000,100000,100000,100000,100000]")
DANGER_ARGS=${DANGER_ARGS#0x}
DANGER=$(cast send --rpc-url $RPC --private-key $PK --create ${DANGER_BC}${DANGER_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${DANGER:-}" ]; then echo "FATAL: EVA_DangerScore deploy failed"; exit 1; fi
echo "EVA_DangerScore = $DANGER"
save_addr DANGER $DANGER
sleep 5
eq_addr "$(cast call $DANGER "HUB()(address)" --rpc-url $RPC)" "$ENGINEHUB" || { echo "FATAL: DANGER hub mismatch"; exit 1; }
sleep 5

echo "  FEEV2=${FEEV2:-MISSING}"
echo "  DANGER=${DANGER:-MISSING}"
echo "Full record: $ADDR_FILE"
echo "=================================================================="
